def consolidate(self, theta_merge: float = 0.12, util_max: int = 2) -> int:
    """Absorbiert episodennahe, wenig genutzte Eintraege in Prototypen.
    Gibt Anzahl absorbierter Episoden zurueck. (M2-Messgegenstand.)"""
    if self.keys.shape[0] == 0:
        return 0
    keep = np.ones(self.keys.shape[0], dtype=bool)
    for i in range(self.keys.shape[0]):
        c = self.vals[i]
        s = sim_from_dh(hamming(self.keys[i], self.P[c:c + 1]))[0]
        if s > theta_merge and self.util[i] < util_max:
            keep[i] = False                        # absorbieren
    removed = int((~keep).sum())
    self.keys, self.vals, self.util = (
        self.keys[keep], self.vals[keep], self.util[keep]
    )
    return removed
